   799					path, err = validateSemanticProviderPath(path)
   800					if err != nil {
   801						return commit(err)
   802					}
   803					record.setSemanticPath(path)
   804					files[path] = record
   805				}
   806			case "symbol":
   807				path := record.semanticPath()
