   816					}
   817				}
   818				if err := insertSemanticSymbol(tx, record); err != nil {
   819					return commit(err)
   820				}
   821			case "relation":
   822				if err := insertSemanticRelation(tx, record); err != nil {
   823					return commit(err)
   824				}
   825			}
   826		}
   827		if err := scanner.Err(); err != nil {
   828			return commit(err)
   829		}
   830	
   831		parseCacheFiles := 0
   832		for path, record := range files {
   833			contentHash := semanticFileContentHash(repoDir, path)
   834			if contentHash == "" && record.Blob != "" {
   835				contentHash = "git-blob:" + record.Blob
   836			}
   837			artifactRel, err := writeSemanticParseCacheArtifact(generationDir, path, record.Blob, contentHash)
   838			if err != nil {
   839				return commit(err)
   840			}
   841			parseCacheFiles++
   842			if _, err := tx.Exec(`INSERT OR REPLACE INTO files(path, blob, content_hash) VALUES (?, ?, ?)`, path, record.Blob, contentHash); err != nil {
   843				return commit(err)
   844			}
   845			if _, err := tx.Exec(`INSERT OR REPLACE INTO parse_cache(path, blob, content_hash, artifact_path) VALUES (?, ?, ?, ?)`, path, record.Blob, contentHash, artifactRel); err != nil {
   846				return commit(err)
   847			}
   848		}
   849	
   850		metrics := semanticBuildMetrics{
   851			GeneratedAt:     now,
   852			GenerationID:    generationID,
   853			Commit:          header.Commit,
   854			Tree:            header.Tree,
   855			Files:           len(files),
   856			Symbols:         counts.Symbols,
   857			Relations:       counts.Relations,
   858			ReverseEdges:    counts.Relations,
   859			Warnings:        len(header.Warnings),
   860			PartialFailures: len(header.PartialFailures),
   861			ParseCacheFiles: parseCacheFiles,
   862		}
   863		metricsJSON, _ := json.Marshal(metrics)
   864		if _, err := tx.Exec(`INSERT OR REPLACE INTO metrics(key, value) VALUES (?, ?)`, "build", string(metricsJSON)); err != nil {
   865			return commit(err)
   866		}
   867		if err := tx.Commit(); err != nil {
   868			return semanticBuildMetrics{}, err
   869		}
   870		return metrics, nil
   871	}
