   925	func writeSemanticParseCacheArtifact(generationDir, path, blob, contentHash string) (string, error) {
   926		key := contentHash
   927		if key == "" {
   928			sum := sha256.Sum256([]byte(path + "\x00" + blob))
   929			key = "sha256:" + hex.EncodeToString(sum[:])
   930		}
   931		if !strings.HasPrefix(key, "sha256:") {
   932			sum := sha256.Sum256([]byte(path + "\x00" + blob + "\x00" + key))
   933			key = "sha256:" + hex.EncodeToString(sum[:])
   934		}
   935		cleanKey := strings.TrimPrefix(key, "sha256:")
   936		if len(cleanKey) < 4 {
   937			cleanKey = hex.EncodeToString([]byte(cleanKey))
   938		}
   939		rel := filepath.Join("parse-cache", cleanKey[:2], cleanKey[2:4], cleanKey+".json")
   940		payload := map[string]string{
   941			"path":         path,
   942			"blob":         blob,
   943			"content_hash": key,
   944		}
   945		data, err := json.MarshalIndent(payload, "", "  ")
   946		if err != nil {
   947			return "", err
   948		}
   949		data = append(data, '\n')
   950		if err := writeFileAtomic(filepath.Join(generationDir, rel), data, 0o600); err != nil {
   951			return "", err
   952		}
   953		return filepath.ToSlash(rel), nil
   954	}
