  1032	func (i brainIgnore) Ignored(path string) bool {
  1033		path = filepath.ToSlash(strings.TrimPrefix(path, "./"))
  1034		if path == ".git" || strings.HasPrefix(path, ".git/") {
  1035			return true
  1036		}
  1037		for _, segment := range []string{"node_modules", "vendor", "dist", "build", "target", ".entire"} {
  1038			if pathHasSegment(path, segment) {
  1039				return true
  1040			}
  1041		}
  1042		for _, pattern := range []string{".env", ".pem", ".key"} {
  1043			if path == pattern || strings.Contains(path, "/"+pattern) || strings.HasSuffix(path, pattern) {
  1044				return true
  1045			}
  1046		}
  1047		for _, pattern := range i.patterns {
  1048			if pattern == path || strings.HasPrefix(path, strings.TrimSuffix(pattern, "/")+"/") {
  1049				return true
  1050			}
  1051			if ok, _ := filepath.Match(pattern, path); ok {
  1052				return true
  1053			}
  1054		}
  1055		return false
  1056	}
