  1071		filtered := make([]semanticWarning, 0, len(warnings))
  1072		for _, warning := range warnings {
  1073			if i.Ignored(warning.Path) || i.MentionsIgnoredPath(warning.Detail) || i.MentionsIgnoredPath(warning.Effect) {
  1074				continue
  1075			}
  1076			filtered = append(filtered, warning)
  1077		}
  1078		return filtered
  1079	}
