  1086		for _, pattern := range append([]string{".env", ".pem", ".key"}, i.patterns...) {
  1087			pattern = strings.Trim(filepath.ToSlash(pattern), "/")
  1088			if pattern != "" && strings.Contains(text, pattern) {
