  1135	func worktreeFingerprint(ctx context.Context, runner CommandRunner, repoDir string) (string, error) {
  1136		status, _, err := runner.Run(ctx, repoDir, "git", "status", "--porcelain")
  1137		if err != nil {
  1138			return "", err
  1139		}
  1140		diff, _, err := runner.Run(ctx, repoDir, "git", "diff", "--binary", "HEAD")
  1141		if err != nil {
  1142			return "", err
  1143		}
  1144		cached, _, err := runner.Run(ctx, repoDir, "git", "diff", "--cached", "--binary", "HEAD")
  1145		if err != nil {
  1146			return "", err
  1147		}
  1148		content := append(append(status, diff...), cached...)
  1149		content = appendUntrackedWorktreeContent(content, repoDir, status)
  1150		sum := sha256.Sum256(content)
  1151		return "sha256:" + hex.EncodeToString(sum[:]), nil
  1152	}
