  1154	func appendUntrackedWorktreeContent(content []byte, repoDir string, status []byte) []byte {
  1155		for _, line := range strings.Split(string(status), "\n") {
  1156			if !strings.HasPrefix(line, "?? ") {
  1157				continue
  1158			}
  1159			path := strings.TrimSpace(strings.TrimPrefix(line, "?? "))
  1160			clean, err := validateSemanticProviderPath(path)
  1161			if err != nil {
  1162				continue
  1163			}
  1164			content = appendWorktreePathContent(content, repoDir, clean)
  1165		}
  1166		return content
  1167	}
  1168	
  1169	func appendWorktreePathContent(content []byte, repoDir, clean string) []byte {
  1170		path := filepath.Join(repoDir, filepath.FromSlash(clean))
  1171		info, err := os.Lstat(path)
  1172		if err != nil || info.Mode()&os.ModeSymlink != 0 {
  1173			return content
  1174		}
  1175		if info.IsDir() {
  1176			_ = filepath.WalkDir(path, func(child string, d os.DirEntry, walkErr error) error {
  1177				if walkErr != nil || d.IsDir() {
  1178					return nil
  1179				}
  1180				rel, err := filepath.Rel(repoDir, child)
  1181				if err != nil {
  1182					return nil
  1183				}
  1184				relSlash := filepath.ToSlash(rel)
  1185				if _, err := validateSemanticProviderPath(relSlash); err != nil {
  1186					return nil
  1187				}
  1188				content = appendFileFingerprintContent(content, child, relSlash)
  1189				return nil
  1190			})
  1191			return content
  1192		}
  1193		return appendFileFingerprintContent(content, path, clean)
  1194	}
  1195	
  1196	func appendFileFingerprintContent(content []byte, path, rel string) []byte {
  1197		data, err := os.ReadFile(path)
  1198		if err != nil {
  1199			return content
  1200		}
  1201		content = append(content, "\x00untracked:"...)
  1202		content = append(content, rel...)
  1203		content = append(content, 0)
  1204		return append(content, data...)
  1205	}
