  1271	func semanticStaleReport(ctx context.Context, opts Options, target string) (staleReport, error) {
  1272		repoDir, local, err := resolveLocalTargetRepoDir(ctx, opts.Runner, target)
  1273		if err != nil {
  1274			return staleReport{}, err
  1275		}
  1276		if !local {
  1277			return staleReport{}, fmt.Errorf("stale requires a local repository path: %s", target)
  1278		}
  1279		storage, err := repoStoragePaths(ctx, opts.Runner, opts.Env, repoDir)
  1280		if err != nil {
  1281			return staleReport{}, err
  1282		}
  1283		manifest, err := loadBrainManifest(storage.BrainDir)
  1284		if err != nil {
  1285			return staleReport{}, err
  1286		}
  1287		axes := map[string]staleAxis{}
  1288		if manifest.Sources == nil || manifest.Sources.Semantic == nil {
  1289			axes["semantic"] = staleAxis{State: "missing", Detail: "no semantic source in manifest"}
  1290			return staleReport{Severity: "unsafe", Axes: axes}, nil
  1291		}
  1292		source := manifest.Sources.Semantic
  1293		if source.SnapshotPath == "" {
  1294			axes["snapshot"] = staleAxis{State: "unsafe", Detail: "semantic snapshot_path is missing"}
  1295		} else if _, err := validateSemanticSnapshotPath(source.SnapshotPath); err != nil {
  1296			axes["snapshot"] = staleAxis{State: "unsafe", Detail: err.Error()}
  1297		} else if err := rejectSymlinkPathComponents(storage.BrainDir, filepath.FromSlash(source.SnapshotPath)); err != nil {
