  1900		entries, err := os.ReadDir(root)
  1901		if err != nil {
  1902			if os.IsNotExist(err) {
  1903				return 0, nil
  1904			}
  1905			return 0, err
  1906		}
  1907		pruned := 0
  1908		for _, entry := range entries {
  1909			if !entry.IsDir() {
  1910				continue
  1911			}
  1912			path := filepath.Join(root, entry.Name())
  1913			if active != "" && filepath.Clean(path) == active {
