  1933	func parseAgeCutoff(value string, now time.Time) (time.Time, error) {
  1934		value = strings.TrimSpace(value)
  1935		if strings.HasSuffix(value, "d") {
  1936			days, err := strconv.Atoi(strings.TrimSuffix(value, "d"))
  1937			if err != nil || days < 0 {
  1938				return time.Time{}, fmt.Errorf("invalid --older-than value: %s", value)
  1939			}
  1940			return now.Add(-time.Duration(days) * 24 * time.Hour), nil
  1941		}
  1942		duration, err := time.ParseDuration(value)
  1943		if err != nil {
  1944			return time.Time{}, fmt.Errorf("invalid --older-than value: %s", value)
  1945		}
  1946		return now.Add(-duration), nil
  1947	}
