    93	func resolveLocalTargetRepoDir(ctx context.Context, runner CommandRunner, target string) (string, bool, error) {
    94		info, err := os.Stat(target)
    95		switch {
    96		case err == nil:
    97		case os.IsNotExist(err):
    98			return "", false, nil
    99		default:
   100			return "", false, fmt.Errorf("stat target path: %w", err)
   101		}
   102	
   103		dir := target
   104		if !info.IsDir() {
   105			dir = filepath.Dir(target)
   106		}
   107		abs, err := filepath.Abs(dir)
   108		if err != nil {
   109			return "", true, fmt.Errorf("resolve target path: %w", err)
   110		}
   111	
   112		if runner != nil {
   113			stdout, _, err := runner.Run(ctx, abs, "git", "rev-parse", "--show-toplevel")
   114			if err == nil {
   115				root := filepath.Clean(strings.TrimSpace(string(stdout)))
   116				if root != "" {
   117					if !filepath.IsAbs(root) {
   118						root = filepath.Join(abs, root)
   119					}
   120					rootAbs, absErr := filepath.Abs(root)
   121					if absErr != nil {
   122						return "", true, fmt.Errorf("resolve git root: %w", absErr)
   123					}
   124					abs = rootAbs
   125				}
   126			}
   127		}
   128	
   129		return abs, true, nil
   130	}
